+      .filter((entry) => entry.isDirectory() && entry.name.endsWith(HOST_PLUGIN_EXTENSION))
+      .map((entry) => path.join(dir, entry.name))
+      .toSorted();
+  } catch (error) {
+    if (error instanceof Error && "code" in error && error.code === "ENOENT") return [];
+    throw error;
+  }
+}
